-- Report ID : RPT_055
-- Report    : Failed Inject Invoices
-- Module    : Finance
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,      ih.INVC_ID                                            AS invoice_id,     ih.INVC_TYPE                                          AS invoice_type,     CASE ih.INVC_TYPE         WHEN 'PP'  THEN 'Purchase Order Invoice'         WHEN 'RC'  THEN 'RTV Credit Note'         WHEN 'CO'  THEN 'Consignment Invoice'         WHEN 'DL'  THEN 'Deal Invoice'         WHEN 'OB'  THEN 'Obligation Invoice'         WHEN 'NM'  THEN 'Non-Merchandise Invoice'         WHEN 'CD'  THEN 'Credit Note'         WHEN 'CR'  THEN 'Credit Note Request'         WHEN 'DM'  THEN 'Debit Memo'         ELSE ih.INVC_TYPE     END                                                   AS invoice_type_desc,     ih.INVC_DATE                                          AS invoice_date,     ih.EXT_REF_NO                                         AS vendor_document_no,      TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE)                  AS days_since_invoice,     CASE         WHEN TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) BETWEEN 0  AND 7         THEN '0 - 7 Days'         WHEN TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) BETWEEN 8  AND 15         THEN '8 - 15 Days'         WHEN TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) BETWEEN 16 AND 30         THEN '16 - 30 Days'         ELSE '30+ Days'     END                                                   AS aging_bucket,      ih.SUPPLIER                                           AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,     ih.PARTNER_ID                                         AS partner_id,     pt.PARTNER_DESC                                       AS partner_name,      ix.ORDER_NO                                           AS po_number,     oh.STATUS                                             AS po_status,     CASE oh.STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE oh.STATUS     END                                                   AS po_status_desc,     ix.LOCATION                                           AS location_id,     ix.LOC_TYPE                                           AS loc_type,     CASE ix.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,      ih.TOTAL_MERCH_COST                                   AS total_invoice_amount,     ih.CURRENCY_CODE                                      AS invoice_currency,     ih.EXCHANGE_RATE                                      AS exchange_rate,     ROUND(ih.TOTAL_MERCH_COST * NVL(ih.EXCHANGE_RATE, 1), 2)                                                           AS total_amt_local_currency,     ih.TERMS                                              AS payment_terms,     ih.DUE_DATE                                           AS payment_due_date,      ih.EDI_SENT_IND                                       AS edi_sent_ind,     ih.EDI_INVC_IND                                       AS edi_invoice_ind,     CASE ih.EDI_SENT_IND         WHEN 'Y' THEN 'EDI Sent to ReIM'         WHEN 'N' THEN 'NOT YET SENT - EDI extract pending'         ELSE          'STATUS UNKNOWN'     END                                                   AS extraction_status,      ih.STATUS                                             AS match_status,     CASE ih.STATUS         WHEN 'U' THEN 'Unmatched'         WHEN 'M' THEN 'Matched'         WHEN 'C' THEN 'Closed'         WHEN 'A' THEN 'Auto-Match Pending'         WHEN 'E' THEN 'Error'         ELSE NVL(ih.STATUS, 'Not Set')     END                                                   AS match_status_desc,     ih.MATCH_FAIL_IND                                     AS match_fail_ind,     ih.MATCH_DATE                                         AS match_date,     ih.MATCH_ID                                           AS match_id,      CASE         WHEN NVL(ih.EDI_SENT_IND, 'N') = 'N'         THEN 'NOT SENT - EDI extract did not process'         WHEN ih.EDI_SENT_IND = 'Y'              AND ih.STATUS = 'E'         THEN 'EXTRACTION ERROR - ReIM rejected the invoice'         WHEN ih.EDI_SENT_IND = 'Y'              AND NVL(ih.STATUS, 'U') = 'U'         THEN 'SENT BUT UNMATCHED - Awaiting ReIM processing'         WHEN NVL(ih.MATCH_FAIL_IND, 'N') = 'Y'         THEN 'MATCH FAILURE - Invoice failed matching process'         ELSE 'UNKNOWN FAILURE - Review EDI and ReIM logs'     END                                                   AS failure_category,      ix.ID                                                 AS xref_id,     ix.SHIPMENT                                           AS linked_shipment_no,      ih.PAID_IND                                           AS paid_ind,     ih.FORCE_PAY_IND                                      AS force_pay_ind,     ih.APPROVAL_DATE                                      AS approval_date,     ih.APPROVAL_ID                                        AS approved_by,     ih.POST_DATE                                          AS post_date,     ih.PAYMENT_DATE                                       AS payment_date,     ih.PAYMENT_REF_NO                                     AS payment_ref_no,     ih.DIRECT_IND                                         AS direct_ind,      id_cnt.LINE_COUNT                                     AS invoice_line_count,     id_cnt.TOTAL_LINE_AMOUNT                              AS total_line_amount,      nm_cnt.NON_MERCH_LINE_COUNT                           AS non_merch_line_count,     nm_cnt.NON_MERCH_TOTAL_AMT                            AS non_merch_total_amount,      ih.CREATE_DATE                                        AS invoice_create_date,     ih.CREATE_ID                                          AS invoice_created_by,      CASE         WHEN NVL(ih.EDI_SENT_IND, 'N') = 'N'         THEN 'Check edidlinv.pc Phase 4 batch log for errors; rerun or reprocess invoice'         WHEN ih.STATUS = 'E'         THEN 'Review ReIM IM_REJECTIONS for error detail; correct invoice and resubmit'         WHEN NVL(ih.STATUS, 'U') = 'U'              AND TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) > 15         THEN 'Invoice aged >15 days unmatched - escalate to AP team for manual match'         WHEN NVL(ih.MATCH_FAIL_IND, 'N') = 'Y'         THEN 'Clear match failure flag; may require ReIM team intervention'         ELSE 'Review edidlinv.pc and ReIM logs; verify invoice staging data is complete'     END                                                   AS recommended_action  FROM     MFCS_RDS.RDS_WV_INVC_HEAD                  ih      LEFT JOIN MFCS_RDS.RDS_WV_INVC_XREF        ix    ON  ih.INVC_ID     = ix.INVC_ID      LEFT JOIN MFCS_RDS.RDS_WV_ORDHEAD           oh    ON  ix.ORDER_NO   = oh.ORDER_NO      LEFT JOIN MFCS_RDS.RDS_WV_SUPS              sp    ON  ih.SUPPLIER   = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_PARTNER           pt    ON  ih.PARTNER_ID = pt.PARTNER_ID      LEFT JOIN MFCS_RDS.RDS_WV_STORE             st    ON  ix.LOCATION   = st.STORE                                                       AND ix.LOC_TYPE   = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH               wh     ON  ix.LOCATION   = wh.WH                                                       AND ix.LOC_TYPE   = 'W'      LEFT JOIN (         SELECT             id.INVC_ID,             COUNT(*)                                      AS line_count,             ROUND(SUM(id.INVC_UNIT_COST * id.INVC_QTY), 2) AS total_line_amount         FROM  MFCS_RDS.RDS_WV_INVC_DETAIL        id         GROUP BY id.INVC_ID     ) id_cnt                                              ON  ih.INVC_ID = id_cnt.INVC_ID      LEFT JOIN (         SELECT             nm.INVC_ID,             COUNT(*)                                      AS non_merch_line_count,             ROUND(SUM(nm.NON_MERCH_AMT), 2)              AS non_merch_total_amt         FROM  MFCS_RDS.RDS_WV_INVC_NON_MERCH     nm         GROUP BY nm.INVC_ID     ) nm_cnt                                              ON  ih.INVC_ID = nm_cnt.INVC_ID  WHERE     (         NVL(ih.EDI_SENT_IND, 'N') = 'N'         OR NVL(ih.STATUS, 'U') NOT IN ('M','C')         OR NVL(ih.MATCH_FAIL_IND, 'N') = 'Y'     )     AND ih.INVC_DATE >= ADD_MONTHS(SYSDATE, -3)  ORDER BY     (TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE)) DESC,     CASE         WHEN NVL(ih.EDI_SENT_IND,'N') = 'N'         THEN 'NOT SENT - EDI extract did not process'         WHEN ih.STATUS = 'E'         THEN 'EXTRACTION ERROR - ReIM rejected the invoice'         WHEN NVL(ih.STATUS,'U') = 'U'         THEN 'SENT BUT UNMATCHED - Awaiting ReIM processing'         ELSE 'MATCH FAILURE'     END,     ih.TOTAL_MERCH_COST DESC,     sp.SUP_NAME,     ih.INVC_ID